<h1>Trades</h1><?php if($editTrade):?><div class="card"><h2>Edit trade #<?=e($editTrade['id'])?></h2><?php $form=$editTrade; include __DIR__.'/trade_form.php';?></div><?php endif;?><div class="card"><h2>Add trade</h2><?php $form=null;include __DIR__.'/trade_form.php';?></div><div class="card"><h2>Trade history (<?=e($total)?>)</h2><form method="get" class="grid"><p><label>Symbol</label><input name="symbol" value="<?=e($filters['symbol'])?>"></p><p><label>Side</label><select name="side"><option value="">All</option><option value="long" <?=$filters['side']==='long'?'selected':''?>>Long</option><option value="short" <?=$filters['side']==='short'?'selected':''?>>Short</option></select></p><p><label>Status</label><select name="status"><option value="">All</option><option value="open" <?=$filters['status']==='open'?'selected':''?>>Open</option><option value="closed" <?=$filters['status']==='closed'?'selected':''?>>Closed</option></select></p><p style="align-self:end"><button>Filter</button></p></form><div class="table-wrap"><table><tr><th>Ticket</th><th>Symbol</th><th>Side</th><th>Status</th><th>Opened</th><th>Qty</th><th>Entry</th><th>Exit</th><th>P&amp;L</th><th></th></tr><?php foreach($trades as $t):?><tr><td><?=e($t['ticket']??'')?></td><td><?=e($t['symbol'])?></td><td><?=e($t['side'])?></td><td><?=e($t['status'])?></td><td><?=e($t['opened_at'])?></td><td><?=e($t['quantity'])?></td><td><?=e($t['entry_price'])?></td><td><?=e($t['exit_price']??'')?></td><td class="<?=($t['pnl']===null?'':($t['pnl']>=0?'positive':'negative'))?>"><?=$t['pnl']===null?'—':number_format($t['pnl'],2)?></td><td><a href="?edit=<?=e($t['id'])?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Delete trade?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($t['id'])?>"><button class="danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$trades):?><tr><td colspan="10" class="muted">No trades found.</td></tr><?php endif;?></table></div><?php if($pages>1):?><p><?php for($p=1;$p<=$pages;$p++):?><a href="?<?=http_build_query(array_merge($filters,['page'=>$p]))?>"><?=$p?></a> <?php endfor;?></p><?php endif;?></div>
